import math
def classify(det, other, known):
    if det["sharp"] > 3.0 or det["pos"] == "f":
        return "bogus"
    if any(math.dist((det["x"], det["y"]), k) < 1.5 for k in known):
        return "known_variable"
    gaps = [math.dist((det["x"], det["y"]), o) for o in other]
    if not any(g < 1.5 for g in gaps) and any(2 <= g <= 8 for g in gaps):
        return "moving"
    return "transient"
dets = [dict(x=10, y=10, sharp=4.2, pos="t"), dict(x=40, y=40.5, sharp=1.2, pos="t"),
        dict(x=70, y=20, sharp=1.1, pos="t")]
print(*[classify(d, [(70, 25)], [(40, 40)]) for d in dets])

import numpy as np
def runs_z(resid):
    s = resid > 0
    n1, n2 = int(s.sum()), int((~s).sum())
    runs = 1 + int(np.sum(s[1:] != s[:-1]))
    mean = 2 * n1 * n2 / (n1 + n2) + 1
    var = 2 * n1 * n2 * (2 * n1 * n2 - n1 - n2) / ((n1 + n2) ** 2 * (n1 + n2 - 1))
    return round(float((runs - mean) / np.sqrt(var)), 2)
print(runs_z(np.array([1, -1] * 10)), runs_z(np.array([1] * 10 + [-1] * 10)))

def release_licence(licences):
    flags = {f for lic in licences for f in ("NC", "SA") if f"-{f}" in lic}
    if flags == {"NC", "SA"}:
        raise ValueError("NC + SA conflict: human review")
    return "CC-BY-" + "".join(f + "-" for f in ("NC", "SA") if f in flags) + "4.0"
